sys_ui_action.script:
(function executeRule(current, previous) {
    try {
        var orchestrator = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestrator.upliftStory();
        gs.addInfoMessage('Story successfully uplifted with INVEST framework and Gherkin syntax. View the AI Manifest for results.');
    } catch (e) {
        gs.addErrorMessage('Story uplift failed: ' + e.message + '. Check the Orchestration Log on the AI Manifest record.');
    }
    action.setRedirectURL(current);
})(current, previous);
